{
  "findings": [
    {
      "ref": "[D546]",
      "area": "contact",
      "claim": "A parent reports that users under 13 can no longer directly message others outside of games or experiences without parental consent.",
      "stance": "risk",
      "quote": "users under the age of 13 will no longer able to directly message others on Roblox outside of games or experiences (also known as platform chat)"
    },
    {
      "ref": "[D546]",
      "area": "contact",
      "claim": "A parent reports that under‑13 users can only communicate in games or experiences via broadcast public chat.",
      "stance": "risk",
      "quote": "users under the age of 13 will be able to communicate using the broadcast public chat"
    },
    {
      "ref": "[D546]",
      "area": "contact",
      "claim": "A parent reports that the legacy chat system and user‑to‑user inbox messaging have been removed.",
      "stance": "risk",
      "quote": "we’ve [removed] the ability for users to message each other via the Roblox Inbox and are removing the legacy chat system by April 30"
    },
    {
      "ref": "[D546]",
      "area": "age_gating",
      "claim": "A parent reports that experiences with social hangouts and free‑form 2D user creation are restricted to users over 13.",
      "stance": "risk",
      "quote": "experiences with certain types of interactive features, specifically social hangouts and free-form 2D user creation, will only be accessible to users over the age of 13"
    },
    {
      "ref": "[D546]",
      "area": "money",
      "claim": "A parent reports that the platform now requires verification via credit card or ID to link parental accounts, raising concerns about accessibility and security.",
      "stance": "risk",
      "quote": "you can link their Roblox account to their child’s account after verifying themselves using an ID or credit card"
    },
    {
      "ref": "[D546]",
      "area": "data",
      "claim": "A parent reports that the new parental controls allow parents to view a child’s friends list and screen‑time activity.",
      "stance": "mitigation",
      "quote": "In the Parental Controls dashboard, parents can now see their child’s screen time over the past week, as well as their child’s friends list"
    },
    {
      "ref": "[D546]",
      "area": "developer_record",
      "claim": "A parent reports that the developer has faced regulatory scrutiny over data collection and age‑gating policies.",
      "stance": "risk",
      "quote": "we’ve added the ability to see what percent of your audience is under 9 years old, to help you better understand the impact these changes will have on your experience(s)"
    }
  ]
}
